(function(scope){
 const defaults={version:1,width:4.6,depth:4.2,bed:'double',style:'cozy',needs:['desk'],motif:'autumn',extras:[],density:55,seed:17,clearance:true};
 const overlap=(a,b,g=0)=>a.x<b.x+b.w+g&&a.x+a.w+g>b.x&&a.y<b.y+b.d+g&&a.y+a.d+g>b.y;
 const inside=(a,w,d)=>a.x>=.02&&a.y>=.02&&a.x+a.w<=w-.02&&a.y+a.d<=d-.02;
 function random(seed){return()=>{seed|=0;seed=seed+0x6D2B79F5|0;let t=Math.imul(seed^seed>>>15,1|seed);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
 function normalize(s){s={...defaults,...s};s.width=Math.max(2.8,Math.min(7,+s.width||4.6));s.depth=Math.max(2.8,Math.min(7,+s.depth||4.2));s.density=Math.max(0,Math.min(100,+s.density||0));s.needs=(s.needs||[]).filter(x=>['desk','reading','storage'].includes(x));s.extras=(s.extras||[]).filter(x=>['whimsy','party'].includes(x));if(!['single','double','king'].includes(s.bed))s.bed='double';if(!['cozy','simple','storybook'].includes(s.style))s.style='cozy';return s;}
 function generate(input){const s=normalize(input),w=s.width,d=s.depth,rng=random(s.seed),door={x:.18,y:d-1.05,w:1.05,d:1.03},items=[],omitted=[];
 const window={x:w-.35-Math.min(1.45,w*.35),y:0,w:Math.min(1.45,w*.35)},bedW={single:.95,double:1.4,king:1.8}[s.bed];
 function access(item){if(item.wall==='top')return{x:item.x,y:item.y+item.d,w:item.w,d:.65};if(item.wall==='bottom')return{x:item.x,y:item.y-.65,w:item.w,d:.65};if(item.wall==='left')return{x:item.x+item.w,y:item.y,w:.65,d:item.d};return{x:item.x-.65,y:item.y,w:.65,d:item.d};}
 function candidates(a,b){let out=[];for(const wall of ['top','right','left','bottom']){const rw=wall==='left'||wall==='right'?b:a,rd=wall==='left'||wall==='right'?a:b;const span=wall==='left'||wall==='right'?d-rd-.12:w-rw-.12;for(let t=.08;t<=span;t+=.18){let x=wall==='left'?.06:wall==='right'?w-rw-.06:t,y=wall==='top'?.06:wall==='bottom'?d-rd-.06:t;const it={x,y,w:rw,d:rd,wall};it.access=access(it);out.push(it);}}return out;}
 function valid(it,placed,protect=true){return inside(it,w,d)&&inside(it.access,w,d)&&!overlap(it,door,.08)&&!overlap(it.access,door,-.1)&&placed.every(p=>!overlap(it,p,.08)&&!overlap(it,p.access,.03)&&(!protect||!overlap(it.access,p,.03)));}
 function route(placed,target){const step=.15,nx=Math.ceil(w/step),ny=Math.ceil(d/step),blocked=(x,y)=>placed.some(p=>x>p.x-.23&&x<p.x+p.w+.23&&y>p.y-.23&&y<p.y+p.d+.23);let start=[Math.floor(.72/step),Math.floor((d-.3)/step)],q=[start],seen=new Set([start.join(',')]);for(let i=0;i<q.length;i++){const[cx,cy]=q[i],x=(cx+.5)*step,y=(cy+.5)*step;if(x>=target.x&&x<=target.x+target.w&&y>=target.y&&y<=target.y+target.d)return true;for(const[dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const a=cx+dx,b=cy+dy,k=a+','+b;if(a<1||b<1||a>=nx-1||b>=ny-1||seen.has(k)||blocked((a+.5)*step,(b+.5)*step))continue;seen.add(k);q.push([a,b]);}}return false;}
 const beds=candidates(bedW,2).filter(c=>c.wall!=='bottom').map(c=>{const gap=.5;c.access=c.wall==='top'?{x:c.x-gap,y:c.y,w:c.w+2*gap,d:c.d+.75}:c.wall==='left'?{x:c.x,y:c.y-gap,w:c.w+.75,d:c.d+2*gap}:{x:c.x-.75,y:c.y-gap,w:c.w+.75,d:c.d+2*gap};c.access.x=Math.max(.03,c.access.x);c.access.y=Math.max(.03,c.access.y);c.access.w=Math.min(c.access.w,w-c.access.x-.03);c.access.d=Math.min(c.access.d,d-c.access.y-.03);c.score=(c.wall==='top'?2:0)-Math.abs(c.x+c.w/2-w*.37)*.3+(rng()-.5)*1.6;return c;}).filter(c=>valid(c,[]));
 beds.sort((a,b)=>b.score-a.score);const bed=beds[0];if(!bed)return{state:s,items:[],omitted:['Bed: room too constrained'],door,window,checks:{reachable:false},decor:[]};
 bed.id='bed';bed.name=s.bed==='single'?'Single bed':s.bed==='king'?'Large bed':'Double bed';bed.reason='A solid wall supports the headboard. Space beside the bed and at its foot is reserved before other furniture is placed.';items.push(bed);
 function add(id,name,a,b,reason,score){let cs=candidates(a,b).filter(c=>valid(c,items));for(const c of cs)c.score=score(c)+(rng()-.5)*.35;cs.sort((a,b)=>b.score-a.score);for(const c of cs.slice(0,40)){const next=[...items,c];if(next.every(p=>route(next,p.access))){Object.assign(c,{id,name,reason});items.push(c);return c;}}omitted.push(name);return null;}
 add('wardrobe','Wardrobe',s.needs.includes('storage')?1.8:1.1,.58,'Storage sits against a wall, with opening space in front. It cannot occupy the doorway or the bed’s access zone.',c=>c.wall==='bottom'?3:c.wall==='right'?2:0);
 if(s.needs.includes('desk'))add('desk','Daylight desk',1.1,.55,'The desk prefers the window. Its chair space must remain connected to the entrance.',c=>5-Math.hypot(c.x+c.w/2-window.x-window.w/2,c.y)*1.2);
 if(s.needs.includes('reading'))add('chair','Reading chair',.78,.8,'A small reading place is added only when its seat remains accessible. A tight room keeps the essentials first.',c=>3-Math.hypot(c.x+c.w/2-window.x,c.y)*.5);
 // A small bedside surface uses bed-local anchors; it may share the wider bed access zone.
 let bedside=bed.wall==='top'?[{x:bed.x-.48,y:.1,w:.4,d:.42},{x:bed.x+bed.w+.08,y:.1,w:.4,d:.42}]:bed.wall==='left'?[{x:.1,y:bed.y-.48,w:.42,d:.4},{x:.1,y:bed.y+bed.d+.08,w:.42,d:.4}]:[{x:w-.52,y:bed.y-.48,w:.42,d:.4},{x:w-.52,y:bed.y+bed.d+.08,w:.42,d:.4}];
 for(const c of bedside){c.wall=bed.wall;c.access=access(c);if(inside(c,w,d)&&!overlap(c,door)&&items.every(p=>!overlap(c,p,.04))){Object.assign(c,{id:'nightstand',name:'Bedside table',reason:'A lamp and a small personal object belong within reach of the bed. This table is placed beside its head, not scattered across the floor.'});if([...items,c].every(p=>route([...items,c],p.access))){items.push(c);break;}}}
 const decor=[];for(const it of items){if(s.density>0){decor.push({id:it.id+'-accent',anchor:it.id,x:it.x+it.w*.75,y:it.y+it.d*.25,kind:it.id==='nightstand'?'lamp':it.id==='desk'?'books':it.id==='wardrobe'?'basket':'pillow'});if(s.density>=45&&it.id==='nightstand')decor.push({id:'motif-object',anchor:it.id,x:it.x+it.w*.25,y:it.y+it.d*.7,kind:s.motif==='halloween'?'pumpkin':'plant'});}}
 if(s.extras.includes('party'))decor.push({id:'garland',anchor:'top-wall',kind:'garland'});if(s.extras.includes('whimsy'))decor.push({id:'stars',anchor:'bed',kind:'stars'});
 return{state:s,items,door,window,omitted,decor,checks:{reachable:items.every(p=>route(items,p.access)),doorClear:items.every(p=>!overlap(p,door)),overlapFree:items.every((a,i)=>items.slice(i+1).every(b=>!overlap(a,b)))}};
 }
 scope.RoomEngine={defaults,normalize,generate,overlap};if(typeof module!=='undefined')module.exports=scope.RoomEngine;
})(typeof window!=='undefined'?window:globalThis);
